# connected components per color
def comps(g,v):
    seen=set(); out=[]
    H,W=len(g),len(g[0])
    for y in range(H):
        for x in range(W):
            if g[y][x]==v and (y,x) not in seen:
                q=[(y,x)];seen.add((y,x));comp=[]
                while q:
                    a,b=q.pop();comp.append((a,b))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            p,q2=a+dy,b+dx
                            if 0<=p<H and 0<=q2<W and g[p][q2]==v and (p,q2) not in seen:
                                seen.add((p,q2));q.append((p,q2))
                out.append(comp)
    return out
